import json
G=[[4]*29 for _ in range(20)]
def frame(r1,c1,r2,c2,color):
    for r in range(r1-1,r2):
        for c in range(c1-1,c2):
            if r in (r1-1,r2-1) or c in (c1-1,c2-1): G[r][c]=color
# Frames from the input
frame(2,2,8,8,9)
frame(5,21,12,28,9)
frame(12,2,15,5,5)
frame(13,13,17,17,6)
# Fill interiors by square side parity: odd -> 7, even -> 2
for r1,c1,r2,c2,fill in [(2,2,8,8,7),(5,21,12,28,2),(12,2,15,5,2),(13,13,17,17,7)]:
    for r in range(r1,r2-1):
        for c in range(c1,c2-1): G[r][c]=fill
